          {value.join(", ")}
        </span>
      </div>
      <Slider
        aria-label="Temperature"
        id="slider-demo-temperature"
        value={value}
        onChange={(value) => setValue(value as number[])}
        minValue={0}
        maxValue={1}
        step={0.1}
      />
    </div>
  )
}

